CREATE TABLE workflow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),product_id uuid NOT NULL,product_version integer NOT NULL,template_version text NOT NULL DEFAULT 'catalog-review/v1',state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN('QUEUED','RUNNING','WAITING_APPROVAL','SUCCEEDED','FAILED')),approval_id uuid REFERENCES approvals(id),package_id uuid REFERENCES publication_packages(id),steps jsonb NOT NULL DEFAULT '[]',error_code text,version integer NOT NULL DEFAULT 1,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,product_id)REFERENCES products(organization_id,id),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
CREATE INDEX workflow_scope ON workflow_runs(organization_id,workspace_id,created_at DESC);
CREATE TABLE mcp_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),label text NOT NULL,token_hash text NOT NULL UNIQUE,request_key text NOT NULL,scopes text[] NOT NULL DEFAULT ARRAY['catalog.read','workflow.read'],active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',UNIQUE(organization_id,user_id,request_key),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
